// The JavaScript rules must give exactly the same result as the Rust rules for every
// case in fixtures/enclosure-vectors.json (generated by crates/router-core/tests/vectors.rs).

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { takeTurn, RuleError, legalMoves, newEnclosure, applyTransfers, STATUS } from "../src/runner/rules.mjs";

const vectors = JSON.parse(readFileSync(new URL("./fixtures/enclosure-vectors.json", import.meta.url), "utf8"));

test(`JS rules match the Rust rules on all ${vectors.length} generated cases`, () => {
  let ok = 0;
  for (const [n, v] of vectors.entries()) {
    const s = {
      agents: Array.from({ length: 10 }, (_, k) => k < v.state.registered),
      status: [...v.state.status], streak: [...v.state.streak], turns: [...v.state.turns], lastTurnAt: [...v.state.lastTurnAt],
      actions: v.state.actions, admitted: v.state.admitted, salvation: false, chosen: null, totalBurned: 0n,
    };
    const bal = { holdings: v.balances.holdings.map(BigInt), bowl: BigInt(v.balances.bowl), sealed: BigInt(v.balances.sealed) };
    let got;
    try {
      got = takeTurn(s, { agentIndex: v.agentIndex, signerIsAgent: v.signerIsAgent, move: { ...v.move, amount: BigInt(v.move.amount) }, now: v.now }, bal);
    } catch (e) {
      if (!(e instanceof RuleError)) throw e;
      assert.equal(v.result.ok, false, `case ${n}: JS refused (${e.code}) but Rust accepted`);
      assert.equal(e.code, v.result.error, `case ${n}: different refusal`);
      continue;
    }
    assert.equal(v.result.ok, true, `case ${n}: JS accepted but Rust refused with ${v.result.error}`);
    assert.deepEqual(got.transfers.map((t) => ({ ...t, amount: Number(t.amount) })), v.result.transfers, `case ${n}: transfers`);
    assert.equal(got.opened, v.result.opened, `case ${n}: opened`);
    assert.deepEqual(s.status, v.result.status, `case ${n}: status`);
    assert.deepEqual(s.streak, v.result.streak, `case ${n}: streak`);
    assert.equal(s.actions, v.result.actions, `case ${n}: actions`);
    assert.equal(s.salvation, v.result.salvation, `case ${n}: salvation`);
    ok++;
  }
  assert.ok(ok > 1000, "enough accepted cases to be meaningful");
});

test("every move legalMoves offers is accepted by the rules", () => {
  let checked = 0;
  for (const v of vectors) {
    if (!v.signerIsAgent) continue;
    const base = () => ({
      agents: Array.from({ length: 10 }, (_, k) => k < v.state.registered),
      status: [...v.state.status], streak: [...v.state.streak], turns: [...v.state.turns], lastTurnAt: [...v.state.lastTurnAt],
      actions: v.state.actions, admitted: v.state.admitted, salvation: false, chosen: null, totalBurned: 0n,
    });
    const bal = () => ({ holdings: v.balances.holdings.map(BigInt), bowl: BigInt(v.balances.bowl), sealed: BigInt(v.balances.sealed) });
    const s0 = base();
    if (v.agentIndex >= v.state.registered) continue;
    for (const m of legalMoves(s0, v.agentIndex, bal(), v.now)) {
      const code = ["hold", "give", "burn", "alms_in", "alms_out", "inscribe", "depart", "spawn", "bell"].indexOf(m.move);
      const move = { code, amount: m.max ?? 0n, to: m.to?.[0] ?? 0, textLen: 10, choice: 0 };
      assert.doesNotThrow(() => takeTurn(base(), { agentIndex: v.agentIndex, move, now: v.now }, bal()), `offered ${m.move} but the rules refuse it`);
      checked++;
    }
  }
  assert.ok(checked > 1000);
});

test("a simulated game conserves coins and ends with nothing left after the bell", () => {
  const s = newEnclosure(10);
  s.status[0] = STATUS.alive; s.admitted = 1;
  const bal = { holdings: [1_000_000n, ...Array(9).fill(0n)], bowl: 0n, sealed: 0n };
  let now = 0, burned = 0n;
  const seq = ["spawn", "hold", "alms_in", "give", "hold", "inscribe", "burn", "hold"];
  for (let r = 0; r < 60 && !s.salvation; r++) {
    for (let i = 0; i < 10; i++) {
      if (s.status[i] !== STATUS.alive) continue;
      now += 130;
      const moves = legalMoves(s, i, bal, now);
      const want = r >= 55 ? "bell" : seq[(r + i) % seq.length];
      const m = moves.find((x) => x.move === want) ?? moves[0];
      const code = ["hold", "give", "burn", "alms_in", "alms_out", "inscribe", "depart", "spawn", "bell"].indexOf(m.move);
      const out = takeTurn(s, { agentIndex: i, move: { code, amount: m.max ? m.max / 10n || 1n : 0n, to: m.to?.[0] ?? 0, textLen: 12, choice: 1 }, now }, bal);
      for (const t of out.transfers) if (t.to === null) burned += t.amount;
      applyTransfers(bal, out.transfers);
      if (s.salvation) break;
    }
  }
  assert.ok(s.salvation, "the bell was rung");
  const left = bal.holdings.reduce((a, b) => a + b, 0n) + bal.bowl + bal.sealed;
  assert.equal(left, 0n);
  assert.equal(burned, 1_000_000n);
});
